import{_ as t,o,c as r,ag as e}from"./chunks/framework.CAXxHpAX.js";const _=JSON.parse('{"title":"性命双修","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-性命双修.md","filePath":"10-核心模型/model-性命双修.md","lastUpdated":1778033203000}'),l={name:"10-核心模型/model-性命双修.md"};function i(n,a,s,h,d,u){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="性命双修" tabindex="-1">性命双修 <a class="header-anchor" href="#性命双修" aria-label="Permalink to &quot;性命双修&quot;">​</a></h1><blockquote><p>了空居士智慧体系的实修功法。 性命双修，既要明心，也要修身。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>性命双修</strong> 是了空居士教导的特色之一。不同于单纯的&quot;禅宗明心见性&quot;，了空居士融合了道家丹道修炼，强调 <strong>心性修养（性功）和身体修炼（命功）同等重要</strong>。心不明则行不正，身不修则气不畅，两者相辅相成。</p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-神守黄房" tabindex="-1">1. 神守黄房 <a class="header-anchor" href="#_1-神守黄房" aria-label="Permalink to &quot;1. 神守黄房&quot;">​</a></h3><p><strong>原文</strong>：神守黄房，金胎自成。黄房乃乾之下、坤之上。</p><p><strong>解读</strong>：黄房指中丹田（膻中穴一带，覆盖整个体腔），神守就是用意识轻轻观照这个区域。这是丹道修炼的第一步。</p><h3 id="_2-似守非守" tabindex="-1">2. 似守非守 <a class="header-anchor" href="#_2-似守非守" aria-label="Permalink to &quot;2. 似守非守&quot;">​</a></h3><p><strong>原文</strong>：不可用心守，不可无意求。</p><p><strong>解读</strong>：这是&quot;火候&quot;的秘诀。守得太紧（有心）就着相，守得太松（无意）就无效。要在有心无心之间——轻轻知道，轻轻放下。</p><h3 id="_3-绵绵若存" tabindex="-1">3. 绵绵若存 <a class="header-anchor" href="#_3-绵绵若存" aria-label="Permalink to &quot;3. 绵绵若存&quot;">​</a></h3><p><strong>原文</strong>：行住坐卧，绵绵若存。</p><p><strong>解读</strong>：不是只有打坐时才观照，而是走路、站着、坐着、躺着，随时保持一种轻轻返观身体的状态。但不能全神贯注到对外界没有知觉的程度。</p><h3 id="_4-抱元守一" tabindex="-1">4. 抱元守一 <a class="header-anchor" href="#_4-抱元守一" aria-label="Permalink to &quot;4. 抱元守一&quot;">​</a></h3><p><strong>原文</strong>：先天元神元炁，刻刻相合，渐渐相化。</p><p><strong>解读</strong>：元神（清净心）和元炁（身体能量）不是割裂的，而是一体的。修炼到深处，神中有气，气中有神，分不开。</p><h3 id="_5-但安神息-不运火而火自运" tabindex="-1">5. 但安神息，不运火而火自运 <a class="header-anchor" href="#_5-但安神息-不运火而火自运" aria-label="Permalink to &quot;5. 但安神息，不运火而火自运&quot;">​</a></h3><p><strong>原文</strong>：只要你心平气和，火候就恰到好处，自然运行。</p><p><strong>解读</strong>：不要刻意调控呼吸或&quot;运气&quot;，心平气和了，一切自自然然。</p><h3 id="_6-百日功灵" tabindex="-1">6. 百日功灵 <a class="header-anchor" href="#_6-百日功灵" aria-label="Permalink to &quot;6. 百日功灵&quot;">​</a></h3><p><strong>原文</strong>：百日功夫，必有变化。十月胎圆，功夫更深。</p><p><strong>解读</strong>：修行不是遥遥无期的事。坚持一百天，一定会有变化。坚持十个月，气场就更加充满。</p><h3 id="_7-形神俱妙" tabindex="-1">7. 形神俱妙 <a class="header-anchor" href="#_7-形神俱妙" aria-label="Permalink to &quot;7. 形神俱妙&quot;">​</a></h3><p><strong>原文</strong>：身体虚无，精神状态好，二者俱佳。</p><p><strong>解读</strong>：形（身体）和神（精神）都达到妙境——身体轻安，精神清明，两者互相促进。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>静坐方法</strong>：</p><ul><li>姿势中正安舒，不要硬撑</li><li>轻轻返观整个体腔（膻中到丹田区域）</li><li>不刻意排除念头，也不跟随念头</li><li>杂念来了，知道了，回来继续观照</li></ul><p><strong>日常练习</strong>：</p><ul><li>走路、做事时，时不时轻轻回到身体的感觉</li><li>口里有话，心里有数，但内心放松</li><li>遇到紧张的事情，先做三次深呼吸，回到身体</li></ul><p><strong>注意事项</strong>：</p><ul><li>&quot;似守非守&quot; 是关键，不要太过专注</li><li>感觉身体发热、发麻、电流感，都是正常现象</li><li>不要追求感觉，感觉是副产品</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 心法是根本，功法是辅助</li><li><a href="/10-核心模型/model-天人合一">天人合一</a> — 性命双修到极致就是天人合一</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 功法也要抓核心，不搞复杂</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>中论丹道</li><li>五篇灵文·温养章</li><li>早年论坛答疑</li></ul><blockquote><p>来源：<a href="/中论丹道_了空居士_完整版(全83篇)">中论丹道_了空居士_完整版(全83篇)</a>&gt;<a href="/五篇灵文_了空居士_完整版">五篇灵文_了空居士_完整版</a> 蒸馏日期：2026-05-05</p></blockquote>',42)])])}const c=t(l,[["render",i]]);export{_ as __pageData,c as default};
